  /**
   * 性别限制（取值域见 SEX_HINT：1 男 / 2 女 / 3 全性别）
   */
  sex: string;
  /**
   * 图标（resources 相对路径，如 clothes/icon/005；管理端列表缩略图与客户端图标共用）
   */
  icon: string;
